<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
import AssistantIcon from './AssistantIcon.vue'
import {relativeDateKey,todoDateLabel,parseTodoDateTime,calendarMonthDays} from '../todo-dates'
const props=defineProps<{modelValue:string;label:string;showShortcuts?:boolean;dateOnly?:boolean}>()
const emit=defineEmits<{'update:modelValue':[value:string]}>()
const popover=ref<HTMLElement|null>(null),input=ref<HTMLInputElement|null>(null),editing=ref(false),draft=ref(''),error=ref(''),now=ref(Date.now()),month=ref(relativeDateKey(Date.now(),0).slice(0,7))
const position=ref({left:'12px',top:'80px'})
const caption=computed(()=>props.modelValue?todoDateLabel(props.modelValue.slice(0,10),now.value)+(props.modelValue.includes('T') && !props.modelValue.endsWith('23:59')?` ${props.modelValue.slice(11)}`:''):'安排日期')
const days=computed(()=>calendarMonthDays(month.value))
watch(()=>props.modelValue,value=>{if(!editing.value)draft.value=value},{immediate:true})
async function begin(){editing.value=true;draft.value=props.modelValue;error.value='';await nextTick();input.value?.select()}
function commit(){if(!editing.value)return;const value=parseTodoDateTime(draft.value,Date.now());if(value===null){error.value='请输入有效日期时间，如 2026-10-22 14:30';input.value?.setCustomValidity(error.value);return}input.value?.setCustomValidity('');if(value!==props.modelValue)emit('update:modelValue',value);editing.value=false;error.value=''}
function cancel(){input.value?.setCustomValidity('');editing.value=false;error.value='';draft.value=props.modelValue}
function show(event:MouseEvent){event.preventDefault();now.value=Date.now();month.value=(props.modelValue||relativeDateKey(now.value,0)).slice(0,7);const box=(event.currentTarget as HTMLElement).getBoundingClientRect(),height=Math.min(310,innerHeight-24);position.value={left:`${Math.max(12,Math.min(box.right-260,innerWidth-272))}px`,top:`${Math.max(12,Math.min(box.bottom+8,innerHeight-height-12))}px`};popover.value?.showPopover()}
function move(offset:number){const date=new Date(`${month.value}-01T12:00:00`);date.setMonth(date.getMonth()+offset);month.value=relativeDateKey(date.getTime(),0).slice(0,7)}
function choose(value:string){const selected=props.dateOnly ? value.slice(0,10) : value && !value.includes('T') ? `${value}T${props.modelValue.slice(11)||'23:59'}`:value;input.value?.setCustomValidity('');emit('update:modelValue',selected);draft.value=selected;editing.value=false;error.value='';popover.value?.hidePopover()}
function shortcut(offset:number){now.value=Date.now();choose(relativeDateKey(now.value,offset))}
function setDate(value:string){choose(value?`${value}T${draft.value.slice(11)||'23:59'}`:'')}
function setClock(value:string){choose(`${draft.value.slice(0,10)||relativeDateKey(Date.now(),0)}T${value||'23:59'}`)}
</script>
<template>
<span class="date-schedule" :class="{'with-shortcuts':showShortcuts,'date-only':dateOnly}"><template v-if="showShortcuts"><button type="button" class="date-quick" :aria-pressed="modelValue.slice(0,10)===relativeDateKey(now,0)" @click="shortcut(0)">今天</button><button type="button" class="date-quick" :aria-pressed="modelValue.slice(0,10)===relativeDateKey(now,1)" @click="shortcut(1)">明天</button></template>
<span class="date-control" :class="{selected:modelValue,'explicit-date':showShortcuts}"><input v-if="showShortcuts" ref="input" class="date-text date-time-input" type="date" :aria-label="label" title="年月日，可自行调整" :value="modelValue.slice(0,10)" @change="setDate(($event.target as HTMLInputElement).value)"/><input v-else ref="input" class="date-text" type="text" :aria-label="label" :aria-invalid="Boolean(error)" :title="error || '点击输入日期时间，日历图标展开整月'" :value="editing?draft:caption" placeholder="安排日期" @focus="begin" @input="draft=($event.target as HTMLInputElement).value" @blur="commit" @keydown.enter.prevent="commit();input?.blur()" @keydown.esc.stop.prevent="cancel();input?.blur()"/><button v-if="!showShortcuts" type="button" class="date-calendar" :aria-label="`${label}打开月历`" aria-haspopup="dialog" @mousedown.prevent @click="show"><AssistantIcon name="calendar"/></button><small v-if="error" class="date-error" role="alert">{{error}}</small></span><label v-if="showShortcuts && !dateOnly" class="date-clock"><input type="time" title="时间" :aria-label="`${label}时间`" :value="modelValue.slice(11)" @change="setClock(($event.target as HTMLInputElement).value)"/></label></span>
<div ref="popover" popover="auto" class="due-date-popover" role="dialog" :aria-label="`${label}选择`" :style="position" @keydown.esc.stop="popover?.hidePopover()"><div class="month-heading"><button type="button" aria-label="上个月" @click="move(-1)">‹</button><b>{{month.slice(0,4)}}年{{Number(month.slice(5))}}月</b><button type="button" aria-label="下个月" @click="move(1)">›</button></div><div class="month-grid"><span v-for="day in ['一','二','三','四','五','六','日']" :key="day">{{day}}</span><button v-for="day in days" :key="day" type="button" :class="{muted:!day.startsWith(month),selected:day===modelValue.slice(0,10),today:day===relativeDateKey(now,0)}" :aria-label="day" :aria-pressed="day===modelValue.slice(0,10)" @click="choose(day)">{{Number(day.slice(-2))}}</button></div><div class="date-shortcuts"><button type="button" @click="choose(relativeDateKey(now,0))">今天</button><button type="button" @click="choose(relativeDateKey(now,1))">明天</button><button type="button" @click="choose('')">不安排</button></div></div>
</template>
<style scoped>
.date-schedule{display:inline-flex;min-width:0;gap:3px;align-items:center}.date-schedule.with-shortcuts{display:grid;grid-template-columns:28px 28px minmax(96px,112px) 76px;width:max-content;max-width:100%;flex:0 1 auto}.date-schedule.with-shortcuts.date-only{grid-template-columns:28px 28px minmax(96px,112px)}.date-clock{display:flex;align-items:center;min-width:0;margin:0;padding:0;border:0;color:inherit}.date-clock input{box-sizing:border-box;width:76px;min-width:0;height:28px;padding:3px;color:inherit;background:#ffffff08;border:1px solid #ffffff28;border-radius:4px;color-scheme:dark;font:11px 'Microsoft YaHei UI',sans-serif}.date-quick{box-sizing:border-box;border:1px solid #ffffff28;border-radius:4px;background:#ffffff08;color:inherit;padding:5px 2px;cursor:pointer;font:10px 'Microsoft YaHei UI',sans-serif;min-height:28px}.date-quick[aria-pressed=true]{border-color:#a4dbb6;background:#a4dbb622;color:#c1efd1}.date-control.explicit-date{max-width:none}.date-control.explicit-date .date-time-input{width:100%;text-align:left;color-scheme:dark}.date-control:not(.explicit-date){max-width:145px}.date-control:not(.explicit-date) .date-text{width:112px}
.date-control{position:relative;display:inline-flex;align-items:center;max-width:105px;min-width:0;border:1px solid #ffffff28;border-radius:4px;background:#ffffff08;color:#dce8df}.date-control.selected{color:#c1efd1;background:#a4dbb610}.date-control .date-text{box-sizing:border-box;min-width:0;width:76px;height:28px;padding:4px 5px;border:0;background:transparent;font:11px 'Microsoft YaHei UI',sans-serif;color:inherit;text-align:center}.date-text[aria-invalid=true]{outline:1px solid #f3b48a}.date-calendar{display:grid;place-items:center;flex:0 0 26px;width:26px;height:28px;border:0;border-left:1px solid #ffffff18;background:transparent;color:inherit;cursor:pointer}.date-calendar svg{width:14px;height:14px}.date-error{position:absolute;right:0;top:100%;z-index:4;max-width:200px;padding:4px;background:#25342c;color:#ffd0c6;font-size:10px}.due-date-popover{position:fixed;inset:auto;margin:0;box-sizing:border-box;width:260px;max-width:calc(100vw - 24px);max-height:calc(100vh - 24px);overflow:auto;padding:10px;border:1px solid #718b78;border-radius:5px;background:#25342c;color:#f4f7f6;font:12px 'Microsoft YaHei UI',sans-serif}.due-date-popover::backdrop{background:transparent}.month-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}.due-date-popover button{font:inherit;color:inherit;border:0;background:transparent;border-radius:3px;cursor:pointer;padding:5px}.month-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:2px;text-align:center}.month-grid>span{font-size:10px;color:#a6bdb0;padding:4px 0}.month-grid button{font-variant-numeric:tabular-nums}.month-grid .muted{opacity:.4}.month-grid .selected{background:#bdddc7;color:#14281b}.month-grid .today{box-shadow:inset 0 0 0 1px #a4dbb6}.date-shortcuts{display:flex;justify-content:space-between;border-top:1px solid #ffffff20;padding-top:5px;margin-top:8px}.due-date-popover button:hover{background:#ffffff1a}.date-control :focus-visible,.due-date-popover :focus-visible{outline:2px solid #a4dbb6;outline-offset:1px}
</style>
